mapper.select:
SELECT A.SEQNO SEQNO, A.CREDIT_MST_ID creditMstId, A.CUSTOMER_ID customerId, A.CREDIT_AMT/100000000 creditAmt, A.VDATE VDATE, A.MDATE MDATE, A.REMARK, C.CUSTOMER_NAME as customerName, D.INSITITUTE_CODE as insitituteCode FROM CREDIT_LINES_PRE A INNER JOIN CREDIT_MST_INFO B on A.CREDIT_MST_ID=B.SEQNO and B.CREDIT_INFO_TYPE in ('01') left join MST_CUSTOMER_INFO C on A.CUSTOMER_ID=C.CUSTOMER_ID left join MST_CUSTOMER_INFO_ADD D on A.CUSTOMER_ID=D.CUSTOMER_ID
A.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
AND to_char(A.VDATE,'yyyy-MM-dd') > = #{vdate,jdbcType=DATE}
AND to_char(A.VDATE,'yyyy-MM-dd') < = #{mdate,jdbcType=DATE}

       SELECT
	 	count(1)
	 FROM 
	 	CREDIT_LINES_PRE A
        where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
         and PARENT_CUSTOMER_ID IS NULL

      and to_char(VDATE,'yyyy-MM-dd')<= #{vmdate, jdbcType=VARCHAR}
       and to_char(MDATE,'yyyy-MM-dd')>=#{vmdate, jdbcType=VARCHAR} 


			 and  SEQNO <> #{seqno}

       SELECT
	 	count(1)
	 FROM 
	 	CREDIT_LINES_PRE A
        where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
         and PARENT_CUSTOMER_ID IS NULL

      and to_char(VDATE,'yyyy-MM-dd')>= #{vdate, jdbcType=VARCHAR}
       and to_char(MDATE,'yyyy-MM-dd')<=#{mdate, jdbcType=VARCHAR} 


			 and  SEQNO <> #{seqno}

       SELECT
	 	count(1)
	 FROM 
	 	CREDIT_LINES 
        where PFLSH = #{pflsh,jdbcType=VARCHAR}

			 and  SEQNO <> #{seqno}
